PRAGMA foreign_keys=ON;
CREATE TABLE institutions (institution_id TEXT PRIMARY KEY,institution_name TEXT NOT NULL,state TEXT NOT NULL,city TEXT NOT NULL,territory TEXT NOT NULL,institution_type TEXT NOT NULL,ownership TEXT NOT NULL,students INTEGER CHECK(students>0),segment TEXT NOT NULL,market_index REAL CHECK(market_index BETWEEN 0 AND 1),is_simulated INTEGER CHECK(is_simulated=1));
CREATE TABLE opportunities (opportunity_id TEXT PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(institution_id),sales_rep TEXT NOT NULL,lead_source TEXT NOT NULL,created TEXT NOT NULL,stage TEXT NOT NULL,value INTEGER CHECK(value>0),expected_close TEXT NOT NULL,actual_close TEXT,status TEXT CHECK(status IN ('Open','Won','Lost')),reason TEXT,CHECK(actual_close IS NULL OR actual_close>=created),CHECK((status='Open' AND actual_close IS NULL) OR (status!='Open' AND actual_close IS NOT NULL)));
CREATE TABLE stage_history (event_id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunities(opportunity_id),stage TEXT NOT NULL,event_date TEXT NOT NULL,UNIQUE(opportunity_id,stage));
CREATE TABLE activities (activity_id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunities(opportunity_id),activity_date TEXT NOT NULL,activity_type TEXT NOT NULL,responded INTEGER CHECK(responded IN(0,1)),follow_up_status TEXT,next_action TEXT,sales_rep TEXT NOT NULL);
CREATE TABLE revenue (contract_id TEXT PRIMARY KEY,opportunity_id TEXT UNIQUE NOT NULL REFERENCES opportunities(opportunity_id),signed_date TEXT NOT NULL,contract_value INTEGER CHECK(contract_value>0),payment_status TEXT,term_days INTEGER CHECK(term_days=365),recognized REAL,recognition_basis TEXT);
CREATE INDEX idx_history_date ON stage_history(event_date);
CREATE INDEX idx_activity_opp ON activities(opportunity_id);
